const actionsRef = React.useRef<Select.Root.Actions>(null);

<Select.Root actionsRef={actionsRef}>
  <Select.Trigger>
    <Select.Value />
  </Select.Trigger>
  <Select.Portal>
    <Select.Positioner>
      <Select.Popup
        onKeyDown={(event) => {
          if (event.ctrlKey && event.key === 'j') {
            event.preventDefault();
            actionsRef.current?.highlightItem('next');
          }
        }}
      >
        {/* items */}
      </Select.Popup>
    </Select.Positioner>
  </Select.Portal>
</Select.Root>;

